files.content:
.loader{
  display:inline-flex;
  align-items:center;
  justify-content:center;
  position:relative;
  flex-shrink:0;
  vertical-align:middle;
  line-height:1;
}
.loader-xs{
  width:var(--loader-xs);
  height:var(--loader-xs);
}
.loader-sm{
  width:var(--loader-sm);
  height:var(--loader-sm);
}
.loader-md{
  width:var(--loader-md);
  height:var(--loader-md);
}
.loader-lg{
  width:var(--loader-lg);
  height:var(--loader-lg);
}
.loader-anim{
  display:block;
  width:100%;
  height:100%;
  object-fit:contain;
  pointer-events:none;
  transition:opacity var(--d-quick) var(--ease-standard), transform var(--d-quick) var(--ease-standard);
}
.loader-fallback{
  position:absolute;
  inset:0;
  display:none;
  align-items:center;
  justify-content:center;
}
.loader-fallback svg{
  width:100%;
  height:100%;
  display:block;
}
.loader-fallback circle{
  fill:none;
  stroke:var(--primary-500);
  stroke-width:2.5;
  stroke-linecap:round;
  stroke-dasharray:60 60;
  stroke-dashoffset:30;
  transform-origin:center;
  animation:loader-spin 1400ms linear infinite;
}
.loader-xs .loader-fallback circle{
  stroke-width:2;
}
.loader-lg .loader-fallback circle{
  stroke-width:3;
}
.loader-with-label{
  display:inline-flex;
  flex-direction:column;
  align-items:center;
  gap:var(--s-3);
  width:auto;
  height:auto;
}
.loader-with-label .loader-anim, .loader-with-label .loader-fallback{
  position:relative;
}
.loader-with-label > .loader-anim, .loader-with-label > .loader-fallback{
  width:var(--loader-md);
  height:var(--loader-md);
  position:relative;
}
.loader-with-label.loader-sm > .loader-anim, .loader-with-label.loader-sm > .loader-fallback{
  width:var(--loader-sm);
  height:var(--loader-sm);
}
.loader-with-label.loader-lg > .loader-anim, .loader-with-label.loader-lg > .loader-fallback{
  width:var(--loader-lg);
  height:var(--loader-lg);
}
.loader-inline{
  display:inline-flex;
  flex-direction:row;
  align-items:center;
  gap:var(--s-2);
  width:auto;
  height:auto;
}
.loader-inline > .loader-anim, .loader-inline > .loader-fallback{
  width:var(--loader-xs);
  height:var(--loader-xs);
  position:relative;
}
.loader-inline.loader-sm > .loader-anim, .loader-inline.loader-sm > .loader-fallback{
  width:var(--loader-sm);
  height:var(--loader-sm);
}
.loader-label{
  font-size:var(--t-body);
  color:var(--obsidian-200);
  letter-spacing:var(--tr-snug);
  white-space:nowrap;
}
.loader-inline .loader-label{
  font-size:var(--t-small);
  color:var(--obsidian-300);
}
.loader-check{
  position:absolute;
  inset:0;
  display:flex;
  align-items:center;
  justify-content:center;
  opacity:0;
  transform:scale(0.5);
  transition:opacity var(--d-quick) var(--ease-standard), transform var(--d-base) var(--ease-spring);
  pointer-events:none;
}
.loader-check svg{
  width:60%;
  height:60%;
  color:var(--success);
}
.loader-overlay{
  position:absolute;
  inset:0;
  display:flex;
  align-items:center;
  justify-content:center;
  background:var(--scrim);
  backdrop-filter:blur(var(--blur-veil));
  z-index:5;
  width:auto;
  height:auto;
  border-radius:inherit;
  opacity:0;
  pointer-events:none;
  transition:opacity var(--d-quick) var(--ease-standard);
}
.loader-page{
  position:absolute;
  inset:0;
  display:flex;
  flex-direction:column;
  align-items:center;
  justify-content:center;
  gap:var(--s-5);
  background:var(--obsidian-950);
  z-index:var(--z-sticky);
}
.loader-comp{
  display:flex;
  flex-direction:column;
  background:var(--obsidian-900);
  border:var(--bw-1) solid var(--obsidian-800);
  border-radius:var(--r-lg);
  overflow:hidden;
  min-height:220px;
}
.loader-comp-head{
  display:flex;
  align-items:center;
  gap:var(--s-3);
  padding:var(--s-4) var(--s-5);
  border-bottom:var(--bw-1) solid var(--obsidian-800);
}
.loader-comp-eyebrow{
  font-family:var(--font-mono);
  font-size:var(--t-micro);
  letter-spacing:var(--tr-mono);
  color:var(--primary-400);
  text-transform:uppercase;
}
.loader-comp-title{
  font-size:var(--t-small);
  font-weight:600;
  color:var(--obsidian-100);
  letter-spacing:var(--tr-snug);
}
.loader-comp-body{
  flex:1;
  display:flex;
  align-items:center;
  justify-content:center;
  padding:var(--s-6);
  position:relative;
}
.loader-comp-actions{
  display:flex;
  gap:var(--s-3);
  padding:var(--s-3) var(--s-5);
  border-top:var(--bw-1) solid var(--obsidian-800);
  background:var(--obsidian-850);
}
.loader-device{
  width:100%;
  height:240px;
  background:var(--obsidian-950);
  border:var(--bw-1) solid var(--obsidian-800);
  border-radius:var(--r-md);
  position:relative;
  overflow:hidden;
}
.loader-device-bar{
  display:flex;
  align-items:center;
  gap:var(--s-1);
  padding:var(--s-2) var(--s-3);
  border-bottom:var(--bw-1) solid var(--obsidian-800);
  background:var(--obsidian-900);
}
.loader-mini-composer{
  display:flex;
  align-items:center;
  gap:var(--s-3);
  padding:var(--s-3);
  background:var(--obsidian-850);
  border:var(--bw-1) solid var(--obsidian-700);
  border-radius:var(--r-lg);
}
.loader-mini-bubble{
  align-self:flex-start;
  margin-bottom:var(--s-3);
  padding:var(--s-3) var(--s-4);
  background:var(--obsidian-800);
  border:var(--bw-1) solid var(--obsidian-700);
  border-radius:var(--r-lg);
  display:inline-flex;
  align-items:center;
  gap:var(--s-3);
  font-size:var(--t-small);
  color:var(--obsidian-200);
}
.loader-scale{
  display:grid;
  grid-template-columns:repeat(4, 1fr);
  gap:var(--s-4);
}
.loader-scale-cell{
  display:flex;
  flex-direction:column;
  align-items:center;
  gap:var(--s-4);
  padding:var(--s-6) var(--s-4);
  background:var(--obsidian-900);
  border:var(--bw-1) solid var(--obsidian-800);
  border-radius:var(--r-md);
  min-height:180px;
  justify-content:center;
}
.loader-scale-cell .loader-anim{
  position:relative;
}
.loader-scale-cell .loader-fallback{
  position:absolute;
  inset:0;
}
.loader-variants{
  display:grid;
  grid-template-columns:repeat(5, minmax(0, 1fr));
  gap:var(--s-4);
}
.loader-variant-cell{
  display:flex;
  flex-direction:column;
  align-items:center;
  justify-content:center;
  gap:var(--s-4);
  padding:var(--s-6) var(--s-4);
  background:var(--obsidian-900);
  border:var(--bw-1) solid var(--obsidian-800);
  border-radius:var(--r-md);
  min-height:220px;
  position:relative;
}
.loader-anatomy{
  display:grid;
  grid-template-columns:minmax(280px, 380px) 1fr;
  gap:var(--s-10);
  padding:var(--s-8);
  background:var(--obsidian-900);
  border:var(--bw-1) solid var(--obsidian-800);
  border-radius:var(--r-lg);
  align-items:center;
}
.loader-anatomy-canvas{
  display:flex;
  flex-direction:column;
  align-items:center;
  gap:var(--s-4);
  padding:var(--s-8);
  background:var(--obsidian-950);
  border:var(--bw-1) solid var(--obsidian-800);
  border-radius:var(--r-md);
}
.loader-anatomy-canvas .loader-anim{
  position:relative;
}
.loader-anatomy-canvas .loader-fallback{
  position:absolute;
  inset:0;
}
.loader-anatomy-legend{
  display:grid;
  gap:var(--s-3);
}
.loader-anatomy-row{
  display:grid;
  grid-template-columns:28px 1fr auto;
  gap:var(--s-3);
  align-items:baseline;
  padding-bottom:var(--s-3);
  border-bottom:var(--bw-1) solid var(--obsidian-800);
}
.loader-anatomy-row:last-child{
  border-bottom:none;
  padding-bottom:0;
}
.loader-anatomy-num{
  font-family:var(--font-mono);
  font-size:var(--t-micro);
  letter-spacing:var(--tr-mono);
  color:var(--primary-400);
}
.loader-anatomy-label{
  font-size:var(--t-small);
  color:var(--obsidian-100);
  font-weight:500;
}
.loader-anatomy-value{
  font-family:var(--font-mono);
  font-size:var(--t-micro);
  letter-spacing:var(--tr-mono);
  color:var(--obsidian-300);
  text-transform:uppercase;
}
@media (prefers-reduced-motion: reduce){
  .loader-anim{
    display:none !important;
  }
  .loader-fallback{
    display:flex;
  }
  .loader-check{
    transition:none;
  }
}
@media (max-width: 720px){
  .loader-scale{
    grid-template-columns:repeat(2, 1fr);
  }
  .loader-variants{
    grid-template-columns:repeat(2, 1fr);
  }
  .loader-anatomy{
    grid-template-columns:1fr;
    padding:var(--s-5);
    gap:var(--s-6);
  }
}
